function perfectpixel_external_current_url() {
	if ( ! function_exists( 'is_product' ) || ! is_product() ) {
		return '';
	}
	$product = wc_get_product( get_queried_object_id() );
	return ( $product && $product->is_type( 'external' ) ) ? $product->get_product_url() : '';
}

function perfectpixel_external_disable_gallery_feature( $enabled ) {
	return perfectpixel_external_current_url() ? false : $enabled;
}

function perfectpixel_external_image_link( $html ) {
	$url = perfectpixel_external_current_url();
	if ( ! $url ) {
		return $html;
	}
	return preg_replace( '/<a href="[^"]*"/', '<a href="' . esc_url( $url ) . '" target="_blank" rel="noopener noreferrer nofollow"', $html, 1 );
}
